#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const MIGRATIONS_DIR = './migrations';

function getAllMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .map(file => ({
                filename: file,
                fullPath: path.join(MIGRATIONS_DIR, file),
                timestamp: extractTimestamp(file)
            }))
            .sort((a, b) => a.timestamp - b.timestamp);

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function extractTimestamp(filename) {
    // Common migration timestamp formats:
    // - Unix timestamp: 1640995200000_filename.sql
    // - ISO-like: 20220101_120000_filename.sql
    // - Sequential: 001_filename.sql, 002_filename.sql

    const timestampMatch = filename.match(/^(\d+)[_-]/);
    if (timestampMatch) {
        return parseInt(timestampMatch[1], 10);
    }

    // If no timestamp found, use filename for alphabetical sorting
    return filename;
}

function logMigrations(migrations) {
    if (migrations.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log('\n=== Migration Scripts (in execution order) ===\n');

    migrations.forEach((migration, index) => {
        console.log(`${index + 1}. ${migration.filename}`);
    });

    console.log(`\nTotal migrations found: ${migrations.length}`);
}

function main() {
    console.log('Reading migration files from:', MIGRATIONS_DIR);

    const migrations = getAllMigrations();
    logMigrations(migrations);
}

// Run the script if executed directly
if (require.main === module) {
    main();
}

module.exports = {
    getAllMigrations,
    extractTimestamp,
    logMigrations
};

-- Create posts table
CREATE TABLE posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id),
    title VARCHAR(255) NOT NULL,
    content TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on user_id for faster queries
CREATE INDEX idx_posts_user_id ON posts(user_id);

-- Add last_login column to users table
ALTER TABLE users ADD COLUMN last_login TIMESTAMP;

-- Add updated_at column for tracking modifications
ALTER TABLE users ADD COLUMN updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

-- Create a trigger to update updated_at automatically
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_users_updated_at 
    BEFORE UPDATE ON users 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

