#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationScript {
    constructor() {
        this.migrationsDir = './migrations/';
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Array of migration file objects with name and full path
     */
    getMigrationFiles() {
        try {
            if (!fs.existsSync(this.migrationsDir)) {
                console.log(`Migrations directory '${this.migrationsDir}' does not exist.`);
                return [];
            }

            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files and sort them alphabetically (which typically gives chronological order)
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort()
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationsDir, file)
                }));

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            return [];
        }
    }

    /**
     * Log the migration files that would be applied
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):\n`);

        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);

            // Optionally read and show a preview of the SQL content
            try {
                const content = fs.readFileSync(file.path, 'utf8');
                const preview = content.length > 100 ? content.substring(0, 100) + '...' : content;
                console.log(`   Preview: ${preview.replace(/\n/g, ' ').trim()}`);
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }

            console.log('');
        });

        console.log('These migrations would be applied in the order shown above.');
    }

    /**
     * Main execution method
     */
    run() {
        this.logMigrations();
    }
}

// Create and run the migration script
const migrationScript = new MigrationScript();
migrationScript.run();

