const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  // Get all migration files sorted by name
  getMigrationFiles() {
    try {
      if (!fs.existsSync(this.migrationsDir)) {
        console.log('Migrations directory does not exist');
        return [];
      }

      const files = fs.readdirSync(this.migrationsDir);

      // Filter for .sql files and sort them alphabetically (which should be chronological)
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort();

      return sqlFiles;
    } catch (error) {
      console.error('Error reading migrations directory:', error.message);
      return [];
    }
  }

  // Log the migration files in order
  logMigrations() {
    console.log('Reading migration files from:', this.migrationsDir);
    console.log('---');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('---');

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('---');
    console.log('Migration files would be applied in this order.');
  }

  // Optional: Read and display SQL content (for debugging)
  displayMigrationContent(filename) {
    try {
      const filePath = path.join(this.migrationsDir, filename);
      const content = fs.readFileSync(filePath, 'utf8');
      console.log(`\nContent of ${filename}:`);
      console.log('---');
      console.log(content);
      console.log('---');
    } catch (error) {
      console.error(`Error reading file ${filename}:`, error.message);
    }
  }
}

// Main execution
function main() {
  const runner = new MigrationRunner();
  runner.logMigrations();
}

// Run if this file is executed directly
if (require.main === module) {
  main();
}

module.exports = MigrationRunner;

-- Migration 001: Create users table
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

