  getDatabaseUrl() {
    try {
      if (!fs.existsSync(this.envFile)) {
        console.log('Environment file (.env.test) not found');
        return null;
      }

      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          return trimmedLine.substring('DATABASE_URL='.length).trim();
        }
      }

      console.log('DATABASE_URL not found in .env.test');
      return null;
    } catch (error) {
      console.error('Error reading environment file:', error.message);
      return null;
    }
  }

  // Log successful connection (simulated)
  logConnection(databaseUrl) {
    if (!databaseUrl) {
      console.log('❌ Could not establish database connection - no DATABASE_URL found');
      return false;
    }

    // Mask password for security
    const maskedUrl = databaseUrl.replace(/:([^:@]+)@/, ':****@');

    console.log(`✅ Successfully resolved database connection:`);
    console.log(`   Connection URL: ${maskedUrl}`);

    // Parse and log connection details (for informational purposes)
    try {
      if (databaseUrl.startsWith('postgres://')) {
        console.log('   Database type: PostgreSQL');
      } else if (databaseUrl.startsWith('mysql://')) {
        console.log('   Database type: MySQL');
      } else if (databaseUrl.startsWith('sqlite://')) {
        console.log('   Database type: SQLite');
