      if (dbMatch) {
        const host = dbMatch[3];
        const dbName = dbMatch[4];
        console.log(`   Host: ${host}`);
        console.log(`   Database: ${dbName}`);
      }
    } catch (parseError) {
      // Silent fail - URL parsing is just for informational logging
    }

    return true;
  }

