#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationScript {
    constructor() {
        this.migrationsDir = './migrations/';
    }

    async run() {
        try {
            console.log('Starting migration script...');
            console.log(`Reading migrations from: ${this.migrationsDir}`);

            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.log('Migrations directory does not exist. Creating it...');
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                console.log('Migrations directory created.');
                console.log('No migrations found.');
                return;
            }

            // Get all SQL files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log('No SQL migration files found.');
                return;
            }

            // Sort files to ensure they are processed in order
            sqlFiles.sort();

            console.log(`\nFound ${sqlFiles.length} migration file(s):`);
            console.log('==========================================');

            // Log each migration file in order
            sqlFiles.forEach((file, index) => {
                const filePath = path.join(this.migrationsDir, file);
                const fileStats = fs.statSync(filePath);
                const fileSize = this.formatFileSize(fileStats.size);

                console.log(`${index + 1}. ${file} (${fileSize})`);
                console.log(`   Path: ${filePath}`);

                // Read and show a preview of the SQL content
                const content = fs.readFileSync(filePath, 'utf8');
                const preview = content.length > 100 
                    ? content.substring(0, 100) + '...' 
                    : content;

                console.log(`   Preview: ${preview.replace(/\n/g, ' ').trim()}`);
                console.log('');
            });

            console.log('Migration files listed in order.');
            console.log('Note: This script only lists the files. To actually apply them,');
            console.log('you would need to integrate with a database library.');

        } catch (error) {
            console.error('Error running migration script:', error.message);
            process.exit(1);
        }
    }

    formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }
}

// If this script is run directly (not imported)
if (require.main === module) {
    const migrationScript = new MigrationScript();
    migrationScript.run();
}

module.exports = MigrationScript;

