const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations/';

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('No migration files found.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = files.filter(file => {
            return file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile();
        });

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in migrations directory.');
            return [];
        }

        // Sort files numerically (assuming they start with numbers like 001_, 002_, etc.)
        sqlFiles.sort((a, b) => {
            // Extract numbers from filenames (assuming format like 001_create_table.sql)
            const numA = parseInt(a.split('_')[0]) || 0;
            const numB = parseInt(b.split('_')[0]) || 0;
            return numA - numB;
        });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function logMigrations(migrations) {
    if (migrations.length === 0) {
        console.log('No migrations to apply.');
        return;
    }

    console.log('Migrations to be applied (in order):');
    console.log('====================================');

    migrations.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);

        // Optional: Log the content of each migration file
        try {
            const content = fs.readFileSync(path.join(MIGRATIONS_DIR, file), 'utf8');
            console.log(`   Preview: ${content.substring(0, 100).replace(/\n/g, ' ').trim()}${content.length > 100 ? '...' : ''}`);
        } catch (error) {
            console.log(`   [Could not read file content: ${error.message}]`);
        }

        console.log(''); // Empty line for readability
    });

    console.log(`Total migrations: ${migrations.length}`);
}

// Main execution
