        if (!databaseUrlMatch) {
            console.log(`DATABASE_URL not found in '${ENV_FILE}'.`);
            return null;
        }

        return databaseUrlMatch[1].trim();
    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return null;
    }
