const fs = require('fs');
const path = require('path');

class MigrationScript {
  constructor() {
    this.migrationsDir = './migrations/';
  }

  // Get all SQL files from migrations directory
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      return files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
          // Extract numbers from filenames for proper ordering
          const numA = this.extractNumber(a);
          const numB = this.extractNumber(b);
          return numA - numB;
        });
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.error(`Error: Migrations directory '${this.migrationsDir}' not found.`);
        console.log('Please create a ./migrations/ directory with your SQL migration files.');
      } else {
        console.error('Error reading migrations directory:', error.message);
      }
      return [];
    }
  }

  // Extract number from filename for sorting (e.g., "001_initial.sql" -> 1)
  extractNumber(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
  }

  // Log migration files that would be applied
  logMigrations() {
    console.log('\n=== Database Migration Script ===');
    console.log('Reading migration files from:', this.migrationsDir);
    console.log('\nMigrations that would be applied (in order):\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal migrations to apply: ${migrationFiles.length}`);
  }

  // Run the migration script
  run() {
    this.logMigrations();
  }
}

// Execute the script
const migrationScript = new MigrationScript();
migrationScript.run();

