extractNumber(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

// Read DATABASE_URL from .env.test file
readDatabaseUrl() {
  try {
    if (!fs.existsSync(this.envFile)) {
      console.log(`Info: Environment file '${this.envFile}' not found.`);
      return null;
    }

    const envContent = fs.readFileSync(this.envFile, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Look for DATABASE_URL
      if (trimmedLine.startsWith('DATABASE_URL=')) {
        const url = trimmedLine.substring('DATABASE_URL='.length).trim();

        // Remove quotes if present
        this.databaseUrl = url.replace(/^['"]|['"]$/g, '');
        return this.databaseUrl;
      }
    }

    console.log(`Info: DATABASE_URL not found in '${this.envFile}'.`);
    return null;

  } catch (error) {
    console.error(`Error reading environment file '${this.envFile}':`, error.message);
    return null;
  }
}

// Log successful connection message
logConnection() {
  const dbUrl = this.readDatabaseUrl();

  if (dbUrl) {
    console.log(`✓ Successfully resolved database connection string from ${this.envFile}`);

    // Mask sensitive parts of the connection string for security
    const maskedUrl = this.maskConnectionString(dbUrl);
    console.log(`  Connection: ${maskedUrl}`);

    return true;
  } else {
    console.log('ℹ No database connection string found. Running in dry-run mode.');
    return false;
  }
}

// Mask sensitive parts of connection string for security
maskConnectionString(url) {
  try {
    // Parse the URL to mask password
    const urlObj = new URL(url);

    if (urlObj.password) {
      urlObj.password = '***';
    }

    return urlObj.toString();
  } catch (error) {
    // If URL parsing fails, return a safely masked version
    return url.replace(/:([^@]+)@/, ':***@');
  }
}

