#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations/';

/**
 * Reads SQL migration files from the migrations directory
 * and returns them sorted in alphabetical order
 */
function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for .sql files
        const sqlFiles = files.filter(file => 
            file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
        );

        // Sort files alphabetically (this typically keeps them in order if named properly)
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

/**
 * Main function to run the migration script
 */
function main() {
    console.log('🔍 Scanning for migration files...\n');

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log(`📋 Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('\n✅ Migration scan completed. These files would be applied in the order shown above.');
}

// Run the script
main();

