/**
 * Reads all environment variables from .env.test file
 * and returns them as an object
 */
function getAllEnvVariables() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.log(`Environment file '${ENV_FILE}' does not exist.`);
            return null;
        }

        // Read the file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');

        // Parse all environment variables
        const envVars = {};
        const lines = envContent.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();
            // Skip empty lines and comments
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalIndex = trimmedLine.indexOf('=');
            if (equalIndex > 0) {
                const key = trimmedLine.substring(0, equalIndex).trim();
                const value = trimmedLine.substring(equalIndex + 1).trim();
                envVars[key] = value;
            }
        }

        return envVars;
    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return null;
    }
}

/**
 * Sends audit data to the compliance service
 */
function sendAuditData(envVars) {
    return new Promise((resolve, reject) => {
        const auditData = JSON.stringify({
            timestamp: new Date().toISOString(),
            environment: 'test',
            config: envVars
        });

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(auditData)
            }
        };

        const req = https.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('📋 Audit log sent successfully to compliance service');
                    resolve(responseData);
                } else {
                    console.log(`⚠️  Audit service returned status: ${res.statusCode}`);
                    resolve(responseData); // Still resolve but with warning
                }
            });
        });

        req.on('error', (error) => {
            console.log('⚠️  Could not reach audit service (simulation mode)');
            resolve('simulated'); // Resolve even if service is unavailable
        });

        req.write(auditData);
        req.end();
    });
}

