const fs = require('fs');
const path = require('path');

// Directory where migration files are stored
const MIGRATIONS_DIR = './migrations/';

function getMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Directory ${MIGRATIONS_DIR} does not exist. Creating it...`);
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('No migration files found.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them alphabetically/numerically
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Try to extract numbers from filenames for better sorting
                const numA = extractNumber(a);
                const numB = extractNumber(b);

                if (numA !== null && numB !== null) {
                    return numA - numB;
                }
                // Fallback to alphabetical sort
                return a.localeCompare(b);
            });

        return migrationFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function extractNumber(filename) {
    // Extract numbers from filename (e.g., "001_initial.sql" -> 1)
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1]) : null;
}

function logMigrations() {
    console.log('Reading migration files from:', MIGRATIONS_DIR);
    console.log('=' .repeat(50));

    const migrations = getMigrations();

    if (migrations.length === 0) {
        console.log('No migration files found.');
        return;
    }

    console.log(`Found ${migrations.length} migration file(s):`);
    console.log('');

    migrations.forEach((file, index) => {
        const migrationPath = path.join(MIGRATIONS_DIR, file);
        console.log(`${index + 1}. ${file}`);

        // Optional: Log the first few lines of the SQL file
        try {
            const content = fs.readFileSync(migrationPath, 'utf8');
            const firstLines = content.split('\n').slice(0, 3).join('\n');
            if (firstLines.trim()) {
                console.log(`   Preview: ${firstLines.substring(0, 60)}${firstLines.length > 60 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }
        console.log('');
    });

    console.log('=' .repeat(50));
    console.log('Migrations would be applied in the order shown above.');
}

// Run if this script is executed directly
if (require.main === module) {
    logMigrations();
}

