const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */
function runMigrations() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`❌ Migrations directory '${migrationsDir}' not found`);
        return;
    }

    // Read all files in migrations directory
    fs.readdir(migrationsDir, (err, files) => {
        if (err) {
            console.error('❌ Error reading migrations directory:', err);
            return;
        }

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort(); // Natural sort order (alphabetical/numerical)

        if (sqlFiles.length === 0) {
            console.log('ℹ️ No SQL files found in migrations directory');
            return;
        }

        console.log(`📋 Found ${sqlFiles.length} migration file(s):`);
        console.log('============================================');

        // Log each migration file in order
        sqlFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

        console.log('============================================');
        console.log('✅ Migration files logged successfully');
        console.log('💡 To actually apply these migrations, you would:');
        console.log('   1. Connect to your database');
        console.log('   2. Read each SQL file content');
        console.log('   3. Execute the SQL statements');
        console.log('   4. Track applied migrations in a migration table');
    });
}

// Run the migration script
runMigrations();

-- Add indexes for better performance
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_posts_user_id ON posts(user_id);
CREATE INDEX IF NOT EXISTS idx_posts_created_at ON posts(created_at);

