#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            if (!fs.existsSync(this.migrationsDir)) {
                console.log(`Migrations directory '${this.migrationsDir}' not found.`);
                return [];
            }

            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort() // Natural sort will order numerically
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationsDir, file)
                }));

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            return [];
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('🔍 Reading migration files from:', this.migrationsDir);
        console.log('\n📋 Migration files to be applied (in order):\n');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);

            // Read and display first few lines of each file
            try {
                const content = fs.readFileSync(file.path, 'utf8');
                const firstLine = content.split('\n')[0].trim();
                if (firstLine) {
                    console.log(`   ${firstLine}`);
                }
            } catch (error) {
                console.log(`   [Error reading file: ${error.message}]`);
            }
            console.log('');
        });

        console.log(`Total migrations found: ${migrationFiles.length}`);
    }

    /**
     * Read the content of a migration file
     * @param {string} filePath - Path to the migration file
     * @returns {string} File content
     */
    readMigrationContent(filePath) {
        try {
            return fs.readFileSync(filePath, 'utf8');
        } catch (error) {
            console.error(`Error reading migration file ${filePath}:`, error.message);
            return '';
        }
    }
}

// Main execution
if (require.main === module) {
    const migrator = new MigrationRunner();
    migrator.logMigrations();
}

module.exports = MigrationRunner;

