const fs = require('fs');
const path = require('path');

// Function to read and process migration files
async function processMigrations() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`Migrations directory '${migrationsDir}' not found.`);
        return;
    }

    // Read all files in migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return;
    }

    // Filter for SQL files only
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => ({
            filename: file,
            fullPath: path.join(migrationsDir, file),
            timestamp: extractTimestamp(file)
        }));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    // Sort by timestamp (if available) or filename
    sqlFiles.sort((a, b) => {
        if (a.timestamp && b.timestamp) {
            return a.timestamp.localeCompare(b.timestamp);
        }
        return a.filename.localeCompare(b.filename);
    });

    console.log('Migration files to apply (in order):');
    console.log('====================================');

    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file.filename}`);

        // Optional: Log file content or metadata
        try {
            // const content = fs.readFileSync(file.fullPath, 'utf8');
            // console.log(`   Preview: ${content.substring(0, 80)}...`);
            const stats = fs.statSync(file.fullPath);
            console.log(`   Size: ${stats.size} bytes, Modified: ${stats.mtime.toLocaleString()}`);
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }
        console.log();
    });

    console.log(`Total migrations to apply: ${sqlFiles.length}`);
}

// Helper function to extract timestamp from filename
// Supports common migration naming patterns like:
// - 20240101120000_create_users_table.sql
// - 001_create_users_table.sql
function extractTimestamp(filename) {
    // Pattern 1: Full timestamp (14 digits)
    const timestampMatch = filename.match(/^(\d{14})_/);
    if (timestampMatch) {
        return timestampMatch[1];
    }

    // Pattern 2: Sequential number (001, 002, etc.)
    const seqMatch = filename.match(/^(\d+)_/);
    if (seqMatch) {
        return seqMatch[1].padStart(14, '0'); // Pad to 14 digits for consistent sorting
    }

    return null; // No timestamp found
}

// Run the migration processor
processMigrations().catch(error => {
    console.error('Migration processing failed:', error);
    process.exit(1);
});

