function loadEnvFile(envFilePath) {
    try {
        if (fs.existsSync(envFilePath)) {
            const envContent = fs.readFileSync(envFilePath, 'utf8');
            const envVars = {};

            envContent.split('\n').forEach(line => {
                const trimmedLine = line.trim();
                // Skip empty lines and comments
                if (trimmedLine && !trimmedLine.startsWith('#')) {
                    const [key, ...valueParts] = trimmedLine.split('=');
                    if (key && valueParts.length > 0) {
                        const value = valueParts.join('=').trim();
                        envVars[key.trim()] = value;
                    }
                }
            });

            return envVars;
        }
    } catch (error) {
        console.warn(`⚠️ Warning: Could not read env file: ${envFilePath}`);
    }
    return {};
}

function parseDatabaseUrl(databaseUrl) {
    try {
        if (!databaseUrl) return null;

        // Parse PostgreSQL URL format: postgres://user:password@host:port/database
        const urlPattern = /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
        const match = databaseUrl.match(urlPattern);

        if (match) {
            return {
                user: match[1],
                password: maskPassword(match[2]),
                host: match[3],
                port: match[4],
                database: match[5],
                original: databaseUrl
            };
        }

        return { original: databaseUrl };
    } catch (error) {
        console.warn('⚠️ Could not parse DATABASE_URL');
        return { original: databaseUrl };
    }
}

