        dbType = 'MySQL';
    } else if (databaseUrl.includes('sqlite://')) {
        dbType = 'SQLite';
    }

    console.log(`\n✅ Successfully connected to ${dbType}`);
    console.log(`   Connection string: ${this.maskSensitiveInfo(databaseUrl)}`);
