/**
 * Read DATABASE_URL from .env.test file
 * @returns {string|null} Database URL or null if not found
 */
getDatabaseUrl() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(this.envFile)) {
            console.log(`Environment file '${this.envFile}' does not exist.`);
            return null;
        }

        // Read file content
        const envContent = fs.readFileSync(this.envFile, 'utf8');

        // Parse DATABASE_URL from file content
        const lines = envContent.split('\n');
        for (const line of lines) {
            const match = line.match(/^DATABASE_URL\s*=\s*(.+)$/);
            if (match) {
                // Remove quotes if present
                let value = match[1].trim();
                if ((value.startsWith('"') && value.endsWith('"')) || 
                    (value.startsWith("'") && value.endsWith("'"))) {
                    value = value.slice(1, -1);
                }
                return value;
            }
        }

        console.log(`DATABASE_URL not found in ${this.envFile}`);
        return null;

    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return null;
    }
}

